def check_critical_path_constraint(task_set):
    for task in task_set:
        if task.L_i > task.D_i:
            return False # Task i cannot be scheduled
    return True

def check_total_utilization_constraint(task_set, num_processors):
    total_utilization = sum(task.u_i for task in task_set)
    if total_utilization > num_processors:
        return False # Task set cannot be scheduled
    return True

